WITH kept_keys AS (SELECT txn_type, account_id FROM transactions EXCEPT ALL SELECT txn_type, account_id FROM transactions WHERE account_id = 22), verified AS (SELECT s.* FROM transactions s INNER JOIN kept_keys k ON s.txn_type = k.txn_type AND s.account_id = k.account_id) SELECT amount, txn_time, is_flagged FROM verified ORDER BY txn_time DESC NULLS LAST, amount
